method correct_bracketing(brackets: string) returns (result: bool)
    requires brackets != null
    ensures result == (CountOpen(brackets) == CountClose(brackets) && NoExcessClose(brackets))

    // Helper function to count opening brackets
    method CountOpen(brackets: string) returns (count: int)
        requires brackets != null
        ensures count >= 0
    {
        count := 0;
        var i := 0;
        while i < brackets.Length
            invariant 0 <= i <= brackets.Length
            invariant count == CountOpening(brackets[0..i])
        {
            if brackets[i] == '(' {
                count := count + 1;
            }
            i := i + 1;
        }
    }

    // Helper function to count closing brackets
    method CountClose(brackets: string) returns (count: int)
        requires brackets != null
        ensures count >= 0
    {
        count := 0;
        var i := 0;
        while i < brackets.Length
            invariant 0 <= i <= brackets.Length
            invariant count == CountClosing(brackets[0..i])
        {
            if brackets[i] == ')' {
                count := count + 1;
            }
            i := i + 1;
        }
    }

    // Helper function to check for excess closing brackets
    method NoExcessClose(brackets: string) returns (valid: bool)
        requires brackets != null
        ensures valid == true || valid == false
    {
        valid := true;
        var openCount := 0;
        var i := 0;
        while i < brackets.Length
            invariant 0 <= i <= brackets.Length
            invariant openCount >= 0
            invariant valid == (openCount >= 0)
        {
            if brackets[i] == '(' {
                openCount := openCount + 1;
            } else if brackets[i] == ')' {
                openCount := openCount - 1;
            }
            i := i + 1;
        }
    }
